INSERT INTO lessons (id, slug, phase_number, lesson_number, title, content_markdown)
VALUES ('eb63a89f-bd59-5968-8ca7-2115501b6863', 'phase-00-lesson-04-cpu-instruction-execution-pipeline-archit', 0, 4, 'CPU Instruction Execution & Pipeline Architecture', '- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 0.1
- **Subtopics**:
  - `0.4.1` The Von Neumann architecture: CPU, memory bus, registers, and arithmetic logic unit (ALU).
  - `0.4.2` The Instruction Cycle: Fetch, Decode, Execute, Memory Access, Write-Back.
