INSERT INTO lessons (id, slug, phase_number, lesson_number, title, content_markdown)
VALUES ('2567337b-0920-59a3-903e-e997c25d8b52', 'phase-00-lesson-27-high-performance-text-processing-grep-sed', 0, 27, 'High-Performance Text Processing (`grep`, `sed`, `awk`, `cut`)', '- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 0.24
