VALUES ('5e9d63fb-3c7f-50db-a384-403a69fd9ab5', 'phase-05-lesson-21-common-table-expressions-ctes-clean-query', 5, 21, 'Common Table Expressions (CTEs): Clean Query Pipelines', '- **Status**: `[State: Active | Complete Specification | Core]`
